// Procedural textures, all generated by code at start-up (seeded, deterministic).
import * as THREE from 'three';
import { mulberry32, clamp, smoothstep, fbm2, simplex2 } from './util.js';

// periodic gradient noise (tileable with period px, py)
function makePerlin(seed) {
  const r = mulberry32(seed);
  const perm = new Uint16Array(512);
  const p = Array.from({ length: 256 }, (_, i) => i);
  for (let i = 255; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [p[i], p[j]] = [p[j], p[i]]; }
  for (let i = 0; i < 512; i++) perm[i] = p[i & 255];
  const gx = new Float32Array(256), gy = new Float32Array(256);
  for (let i = 0; i < 256; i++) { const a = r() * Math.PI * 2; gx[i] = Math.cos(a); gy[i] = Math.sin(a); }
  const fade = (t) => t * t * t * (t * (t * 6 - 15) + 10);
  return function (x, y, px, py) {
    const xi = Math.floor(x), yi = Math.floor(y);
    const xf = x - xi, yf = y - yi;
    const x0 = ((xi % px) + px) % px, y0 = ((yi % py) + py) % py;
    const x1 = (x0 + 1) % px, y1 = (y0 + 1) % py;
    const h = (a, b) => perm[perm[a & 255] + (b & 255)];
    const g = (hh, dx, dy) => gx[hh] * dx + gy[hh] * dy;
    const n00 = g(h(x0, y0), xf, yf), n10 = g(h(x1, y0), xf - 1, yf);
    const n01 = g(h(x0, y1), xf, yf - 1), n11 = g(h(x1, y1), xf - 1, yf - 1);
    const u = fade(xf), v = fade(yf);
    return (n00 * (1 - u) + n10 * u) * (1 - v) + (n01 * (1 - u) + n11 * u) * v;
  };
}
function pfbm(noise, x, y, period, oct) {
  let s = 0, a = 1, n = 0, f = 1;
  for (let o = 0; o < oct; o++) { s += a * noise(x * f, y * f, period * f, period * f); n += a; a *= 0.5; f *= 2; }
  return s / n;
}

function dataTex(data, w, h, { srgb = true, repeat = false, aniso = 8 } = {}) {
  const t = new THREE.DataTexture(data, w, h, THREE.RGBAFormat);
  t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  t.generateMipmaps = true;
  t.minFilter = THREE.LinearMipmapLinearFilter;
  t.magFilter = THREE.LinearFilter;
  t.anisotropy = aniso;
  if (repeat) { t.wrapS = t.wrapT = THREE.RepeatWrapping; }
  t.flipY = false;
  t.needsUpdate = true;
  return t;
}

// height (Float32, w*h) -> normal map RGBA
function heightToNormal(hgt, w, h, strength, wrap) {
  const out = new Uint8Array(w * h * 4);
  const H = (x, y) => {
    if (wrap) { x = (x + w) % w; y = (y + h) % h; } else { x = clamp(x, 0, w - 1); y = clamp(y, 0, h - 1); }
    return hgt[y * w + x];
  };
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const dx = (H(x + 1, y) - H(x - 1, y)) * strength;
    const dy = (H(x, y + 1) - H(x, y - 1)) * strength;
    let nx = -dx, ny = dy, nz = 1; // texture v grows downwards in data, flipY=false
    const l = Math.hypot(nx, ny, nz); nx /= l; ny /= l; nz /= l;
    const i = (y * w + x) * 4;
    out[i] = (nx * 0.5 + 0.5) * 255; out[i + 1] = (ny * 0.5 + 0.5) * 255; out[i + 2] = (nz * 0.5 + 0.5) * 255; out[i + 3] = 255;
  }
  return out;
}

// Tileable moon-dust surface: albedo + normal + roughness. ~1 tile per 3 m.
export function regolithTextures(size = 1024) {
  const noise = makePerlin(11), noise2 = makePerlin(23);
  const r = mulberry32(5);
  const hgt = new Float32Array(size * size);
  const alb = new Uint8Array(size * size * 4);
  const P = 8;
  for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {
    const u = (x / size) * P, v = (y / size) * P;
    const big = pfbm(noise, u, v, P, 5);
    const fine = pfbm(noise2, u * 8, v * 8, P * 8, 3);
    hgt[y * size + x] = big * 0.6 + fine * 0.25;
  }
  // pebbles + micro craters stamped into the height field
  const stamp = (cx, cy, rad, amp, crater) => {
    const r0 = Math.ceil(rad * 1.6);
    for (let dy = -r0; dy <= r0; dy++) for (let dx = -r0; dx <= r0; dx++) {
      const d = Math.hypot(dx, dy) / rad;
      if (d > 1.6) continue;
      const xx = (cx + dx + size) % size, yy = (cy + dy + size) % size;
      let v;
      if (crater) v = d < 1 ? -(1 - d * d) * amp : Math.exp(-((d - 1.05) ** 2) * 30) * amp * 0.45;
      else v = d < 1 ? Math.sqrt(1 - d * d) * amp : 0;
      hgt[yy * size + xx] += v;
    }
  };
  for (let i = 0; i < 260; i++) stamp(Math.floor(r() * size), Math.floor(r() * size), 1.5 + r() * r() * 9, 0.12 + r() * 0.25, true);
  for (let i = 0; i < 1400; i++) stamp(Math.floor(r() * size), Math.floor(r() * size), 0.8 + r() * r() * 3.5, 0.25 + r() * 0.4, false);
  for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {
    const i = y * size + x;
    const u = (x / size) * P, v = (y / size) * P;
    const tone = pfbm(noise, u * 0.5 + 3.3, v * 0.5 + 1.1, P * 0.5, 3);
    const speck = r();
    let g = 0.50 + tone * 0.10 + hgt[i] * 0.05;
    if (speck > 0.985) g += 0.10; else if (speck < 0.012) g -= 0.12;
    g = clamp(g, 0, 1);
    const c = g * 255;
    alb[i * 4] = c * 0.985; alb[i * 4 + 1] = c * 0.99; alb[i * 4 + 2] = c; alb[i * 4 + 3] = 255;
  }
  const nrm = heightToNormal(hgt, size, size, 2.2, true);
  return {
    map: dataTex(alb, size, size, { repeat: true }),
    normalMap: dataTex(nrm, size, size, { srgb: false, repeat: true }),
  };
}

// The cross-section of the ground (the "cake slice"): layered dust and rock.
// Covers worldW x worldH metres; u: x from -worldW/2, v: y from 0 down to -worldH.
export function strataTextures(worldW = 28, worldH = 14, pxPerM = 140) {
  const w = Math.round(worldW * pxPerM), h = Math.round(worldH * pxPerM);
  const noise = makePerlin(77);
  const r = mulberry32(99);
  // layer boundaries (metres below surface), wavy
  const b1 = (xm) => 0.32 + 0.05 * simplex2(xm * 0.7, 1.3);                  // fine top dust
  const b2 = (xm) => 2.6 + 0.35 * fbm2(xm * 0.25, 4.2, 3);                    // regolith
  const b3 = (xm) => 5.4 + 0.6 * fbm2(xm * 0.18, 8.7, 3);                     // broken rock
  const alb = new Float32Array(w * h * 3);
  const hgt = new Float32Array(w * h);
  for (let y = 0; y < h; y++) {
    const dm = y / pxPerM;
    for (let x = 0; x < w; x++) {
      const xm = x / pxPerM;
      const i = y * w + x;
      const n1 = noise(xm * 3.1, dm * 3.1, 256, 256), n2 = noise(xm * 11, dm * 11, 256, 256), n3 = noise(xm * 37, dm * 37, 512, 512);
      let c;
      if (dm < b1(xm)) { c = [0.66, 0.655, 0.65]; }
      else if (dm < b2(xm)) { const k = (dm - b1(xm)) / (b2(xm) - b1(xm)); c = [0.56 - k * 0.08, 0.545 - k * 0.08, 0.53 - k * 0.07]; }
      else if (dm < b3(xm)) { c = [0.40, 0.405, 0.43]; }
      else {
        // basalt bedrock with faint strata
        const band = Math.sin((dm + 0.4 * fbm2(xm * 0.2, dm * 0.1, 2)) * 5.3) * 0.5 + 0.5;
        c = [0.27 + band * 0.05, 0.28 + band * 0.05, 0.315 + band * 0.055];
      }
      const g = n1 * 0.05 + n2 * 0.04 + n3 * 0.035;
      alb[i * 3] = c[0] + g; alb[i * 3 + 1] = c[1] + g; alb[i * 3 + 2] = c[2] + g;
      hgt[i] = n2 * 0.4 + n3 * 0.35 + n1 * 0.3;
      // soft boundary lines between layers
      const dl = Math.min(Math.abs(dm - b2(xm)), Math.abs(dm - b3(xm)));
      if (dl < 0.03) { const k = 1 - dl / 0.03; alb[i * 3] -= 0.05 * k; alb[i * 3 + 1] -= 0.05 * k; alb[i * 3 + 2] -= 0.05 * k; }
    }
  }
  // embedded rocks: angular, faceted polygons (like broken rock), more and bigger with depth
  const LX = -0.55, LY = -0.83; // light from upper-left (texture y grows downwards)
  const rock = (cx, cy, rad, shade) => {
    const nv = 5 + Math.floor(r() * 4);
    const ang0 = r() * 6.28;
    const vx = [], vy = [];
    for (let k = 0; k < nv; k++) {
      const a = ang0 + (k / nv) * Math.PI * 2 + (r() - 0.5) * 0.7;
      const rr = rad * (0.55 + r() * 0.5);
      vx.push(Math.cos(a) * rr); vy.push(Math.sin(a) * rr * (0.65 + r() * 0.35));
    }
    const ax = (r() - 0.5) * rad * 0.5, ay = (r() - 0.5) * rad * 0.5; // apex
    const fshade = [];
    for (let k = 0; k < nv; k++) {
      const k2 = (k + 1) % nv;
      const mx = (vx[k] + vx[k2]) / 2 - ax, my = (vy[k] + vy[k2]) / 2 - ay;
      const l = Math.hypot(mx, my) || 1;
      fshade.push(shade + ((mx / l) * LX + (my / l) * LY) * 0.11 + (r() - 0.5) * 0.03);
    }
    const R = Math.ceil(rad * 1.1);
    for (let dy = -R; dy <= R; dy++) {
      const yy = cy + dy; if (yy < 0 || yy >= h) continue;
      for (let dx = -R; dx <= R; dx++) {
        const xx = cx + dx; if (xx < 0 || xx >= w) continue;
        // which wedge (apex, v_k, v_k+1) contains the point?
        let inside = false, k = 0, e = 0;
        for (k = 0; k < nv; k++) {
          const k2 = (k + 1) % nv;
          const ex = vx[k2] - vx[k], ey = vy[k2] - vy[k];
          const c0 = (vx[k] - ax) * (dy - ay) - (vy[k] - ay) * (dx - ax);
          const c1 = ex * (dy - vy[k]) - ey * (dx - vx[k]);
          const c2 = (ax - vx[k2]) * (dy - vy[k2]) - (ay - vy[k2]) * (dx - vx[k2]);
          if ((c0 >= 0 && c1 >= 0 && c2 >= 0) || (c0 <= 0 && c1 <= 0 && c2 <= 0)) {
            inside = true;
            e = Math.abs(c1) / (Math.hypot(ex, ey) || 1); // distance to outer edge
            break;
          }
        }
        if (!inside) continue;
        const i = yy * w + xx;
        const edge = 1 - smoothstep(0, Math.max(1.5, rad * 0.12), e);
        const v = fshade[k] - edge * 0.09;
        alb[i * 3] = v; alb[i * 3 + 1] = v; alb[i * 3 + 2] = v * 1.025;
        hgt[i] = 1.0 + Math.min(e, rad * 0.4) * 0.06;
      }
    }
  };
  const count = Math.round(worldW * worldH * 7);
  for (let k = 0; k < count; k++) {
    const xm = r() * worldW, dm = 0.4 + r() * (worldH - 0.4);
    let rad = 0.02 + r() * r() * 0.09;
    let shade = 0.40 + r() * 0.22;
    if (dm > 2.6) { rad *= 1.7; shade -= 0.06; }
    if (dm > 5.4) { rad *= 1.4; shade -= 0.06; if (r() < 0.55) continue; }
    rock(Math.floor(xm * pxPerM), Math.floor(dm * pxPerM), rad * pxPerM, shade);
  }
  // a few large boulders deep down
  for (let k = 0; k < Math.round(worldW * 0.8); k++) {
    const xm = r() * worldW, dm = 3.2 + r() * (worldH - 3.5);
    rock(Math.floor(xm * pxPerM), Math.floor(dm * pxPerM), (0.25 + r() * 0.45) * pxPerM, 0.30 + r() * 0.12);
  }
  // cracks in bedrock
  for (let k = 0; k < Math.round(worldW * 1.2); k++) {
    let xm = r() * worldW, dm = 5.6 + r() * (worldH - 6);
    let a = r() * Math.PI * 2;
    for (let s = 0; s < 120; s++) {
      a += (r() - 0.5) * 0.6;
      xm += Math.cos(a) * 0.01; dm += Math.sin(a) * 0.01;
      const x = Math.floor(xm * pxPerM), y = Math.floor(dm * pxPerM);
      if (x < 1 || y < 1 || x >= w - 1 || y >= h - 1) break;
      for (const [ox, oy] of [[0, 0], [1, 0], [0, 1]]) { const i = (y + oy) * w + x + ox; alb[i * 3] *= 0.7; alb[i * 3 + 1] *= 0.7; alb[i * 3 + 2] *= 0.7; hgt[i] -= 1.0; }
    }
  }
  const data = new Uint8Array(w * h * 4);
  for (let i = 0; i < w * h; i++) {
    data[i * 4] = clamp(alb[i * 3]) * 255; data[i * 4 + 1] = clamp(alb[i * 3 + 1]) * 255; data[i * 4 + 2] = clamp(alb[i * 3 + 2]) * 255; data[i * 4 + 3] = 255;
  }
  const nrm = heightToNormal(hgt, w, h, 0.9, false);
  return {
    map: dataTex(data, w, h), normalMap: dataTex(nrm, w, h, { srgb: false }),
    worldW, worldH,
  };
}

// Earth: equirectangular albedo (+ clouds in alpha of a second texture)
export function earthTextures(w = 1024, h = 512) {
  const data = new Uint8Array(w * h * 4), cl = new Uint8Array(w * h * 4);
  for (let y = 0; y < h; y++) {
    const lat = (0.5 - y / h) * Math.PI;
    for (let x = 0; x < w; x++) {
      const lon = (x / w) * Math.PI * 2;
      const px = Math.cos(lat) * Math.cos(lon), py = Math.sin(lat), pz = Math.cos(lat) * Math.sin(lon);
      // sample 2D noise on a sphere by mixing two planes (avoids seams)
      const n = 0.6 * fbm2(px * 1.6 + 3, pz * 1.6 + py * 0.9, 5) + 0.4 * fbm2(py * 1.7 - 2, px * 1.4 + pz, 5);
      const ice = smoothstep(0.78, 0.86, Math.abs(Math.sin(lat)) + 0.04 * n);
      const land = smoothstep(0.03, 0.07, n);
      const dry = smoothstep(0.25, 0.6, 1 - Math.abs(Math.sin(lat)) * 1.6 + 0.6 * fbm2(px * 4, pz * 4 + py * 2, 3));
      let c = [0.03, 0.16 + 0.08 * (1 - Math.abs(n)), 0.48 + 0.14 * (1 - Math.abs(n))];
      const shallow = smoothstep(-0.05, 0.04, n) * (1 - land);
      c = c.map((v, k) => v + shallow * [0.02, 0.10, 0.12][k]);
      const lc = [0.22 + 0.42 * dry, 0.45 + 0.12 * dry, 0.14 + 0.12 * dry];
      c = c.map((v, k) => v * (1 - land) + lc[k] * land);
      c = c.map((v) => v * (1 - ice) + 0.92 * ice);
      const i = (y * w + x) * 4;
      data[i] = clamp(c[0]) * 255; data[i + 1] = clamp(c[1]) * 255; data[i + 2] = clamp(c[2]) * 255; data[i + 3] = 255;
      const cn = fbm2(px * 3.2 + 7, py * 3.2 + pz * 1.5, 6) + 0.35 * fbm2(pz * 9, px * 9 + py, 3);
      const band = 0.2 * Math.cos(lat * 6);
      const cloud = smoothstep(0.22, 0.55, cn + band);
      cl[i] = 255; cl[i + 1] = 255; cl[i + 2] = 255; cl[i + 3] = cloud * 220;
    }
  }
  const map = dataTex(data, w, h); map.wrapS = THREE.RepeatWrapping;
  const clouds = dataTex(cl, w, h); clouds.wrapS = THREE.RepeatWrapping;
  return { map, clouds };
}

// fine fabric weave normal map for the spacesuit (tileable)
export function fabricNormal(size = 256) {
  const hgt = new Float32Array(size * size);
  const noise = makePerlin(3);
  for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {
    const wx = Math.sin((x / size) * Math.PI * 2 * 48), wy = Math.sin((y / size) * Math.PI * 2 * 48);
    hgt[y * size + x] = 0.25 * (wx > 0 ? wy : -wy) + 0.4 * pfbm(noise, (x / size) * 4, (y / size) * 4, 4, 3);
  }
  return dataTex(heightToNormal(hgt, size, size, 1.2, true), size, size, { srgb: false, repeat: true });
}

// boot print (tread) normal + alpha mask
export function footprintTexture(w = 128, h = 256) {
  const hgt = new Float32Array(w * h), mask = new Uint8Array(w * h * 4);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const u = (x / w - 0.5) * 2, v = (y / h - 0.5) * 2;
    // rounded boot outline
    const shape = Math.pow(Math.abs(u) / (0.78 - 0.1 * v), 2.4) + Math.pow(Math.abs(v) / 0.95, 2.4);
    const inside = 1 - smoothstep(0.85, 1.0, shape);
    const tread = (Math.sin(v * 38) > 0.15 ? 1 : 0) * (Math.abs(u) < 0.62 ? 1 : 0);
    hgt[y * w + x] = -inside * (0.8 + 0.35 * tread) + Math.exp(-Math.pow((shape - 1.0) * 5, 2)) * 0.35;
    const i = (y * w + x) * 4;
    mask[i] = 255; mask[i + 1] = 255; mask[i + 2] = 255; mask[i + 3] = clamp(inside * 1.0 + Math.exp(-Math.pow((shape - 1.0) * 4, 2)) * 0.6) * 255;
  }
  return {
    normalMap: dataTex(heightToNormal(hgt, w, h, 2.5, false), w, h, { srgb: false }),
    alphaMap: dataTex(mask, w, h, { srgb: false }),
  };
}

// --- canvas-drawn graphics (flag, icons, screens) ---------------------------
function canvasTex(w, h, draw, srgb = true) {
  const c = document.createElement('canvas'); c.width = w; c.height = h;
  const g = c.getContext('2d');
  draw(g, w, h);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  t.anisotropy = 8;
  t.generateMipmaps = true;
  t.minFilter = THREE.LinearMipmapLinearFilter;
  return t;
}
function starPath(g, cx, cy, R, r) {
  g.beginPath();
  for (let i = 0; i < 10; i++) {
    const a = -Math.PI / 2 + (i * Math.PI) / 5;
    const rr = i % 2 ? r : R;
    g.lineTo(cx + Math.cos(a) * rr, cy + Math.sin(a) * rr);
  }
  g.closePath();
}
export function flagTexture() {
  return canvasTex(512, 340, (g, w, h) => {
    const grd = g.createLinearGradient(0, 0, w, h);
    grd.addColorStop(0, '#2f7fe0'); grd.addColorStop(1, '#2163c4');
    g.fillStyle = grd; g.fillRect(0, 0, w, h);
    g.fillStyle = 'rgba(255,255,255,0.12)'; g.fillRect(0, h * 0.86, w, h * 0.14);
    starPath(g, w / 2, h / 2 + 6, 112, 46);
    g.fillStyle = '#ffd34a'; g.fill();
    g.lineWidth = 8; g.strokeStyle = '#fff3c2'; g.stroke();
  });
}
function roundRect(g, x, y, w, h, r) { g.beginPath(); g.roundRect(x, y, w, h, r); }
// signal bars with a big red cross
export function noSignalTexture() {
  return canvasTex(512, 512, (g, w, h) => {
    g.clearRect(0, 0, w, h);
    roundRect(g, 18, 18, w - 36, h - 36, 110); g.fillStyle = 'rgba(255,255,255,0.96)'; g.fill();
    g.lineWidth = 14; g.strokeStyle = '#e8eef7'; g.stroke();
    const bw = 58, gap = 26, base = 400, x0 = 104;
    for (let i = 0; i < 4; i++) {
      const bh = 70 + i * 70;
      roundRect(g, x0 + i * (bw + gap), base - bh, bw, bh, 16);
      g.fillStyle = '#5d6b80'; g.fill();
    }
    g.lineCap = 'round';
    g.beginPath(); g.moveTo(120, 120); g.lineTo(392, 392); g.moveTo(392, 120); g.lineTo(120, 392);
    g.strokeStyle = '#8a0010'; g.lineWidth = 66; g.stroke();
    g.strokeStyle = '#ff1a2e'; g.lineWidth = 48; g.stroke();
  });
}
// O2 bubble with a cross (for "no air")
export function noAirTexture() {
  return canvasTex(512, 512, (g, w, h) => {
    g.beginPath(); g.arc(w / 2, h / 2, 230, 0, Math.PI * 2); g.fillStyle = 'rgba(255,255,255,0.95)'; g.fill();
    g.lineWidth = 20; g.strokeStyle = '#ff3b4a'; g.stroke();
    g.fillStyle = '#5b6b80'; g.font = 'bold 200px "DejaVu Sans", sans-serif'; g.textAlign = 'center'; g.textBaseline = 'middle';
    g.fillText('O', w / 2 - 30, h / 2 + 8); g.font = 'bold 110px "DejaVu Sans", sans-serif'; g.fillText('2', w / 2 + 92, h / 2 + 70);
    g.lineCap = 'round'; g.strokeStyle = '#ff2d3d'; g.lineWidth = 40;
    g.beginPath(); g.moveTo(110, 110); g.lineTo(402, 402); g.stroke();
  });
}
export function checkTexture() {
  return canvasTex(256, 256, (g, w, h) => {
    g.beginPath(); g.arc(w / 2, h / 2, 116, 0, Math.PI * 2); g.fillStyle = '#2bd27a'; g.fill();
    g.lineCap = 'round'; g.lineJoin = 'round'; g.strokeStyle = '#ffffff'; g.lineWidth = 30;
    g.beginPath(); g.moveTo(70, 132); g.lineTo(112, 172); g.lineTo(188, 88); g.stroke();
  });
}
// thermometer gauge dial: drawn per frame by the caller using drawThermo()
export function makeCanvas(w, h) {
  const c = document.createElement('canvas'); c.width = w; c.height = h;
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 8;
  return { canvas: c, ctx: c.getContext('2d'), tex: t };
}
export function drawThermo(g, w, h, level, color) {
  // level 0..1 ; color css
  g.clearRect(0, 0, w, h);
  const cx = w / 2;
  roundRect(g, cx - 34, 20, 68, h - 120, 34); g.fillStyle = 'rgba(255,255,255,0.95)'; g.fill();
  g.beginPath(); g.arc(cx, h - 70, 56, 0, Math.PI * 2); g.fill();
  roundRect(g, cx - 18, 36, 36, h - 140, 18); g.fillStyle = '#dfe6ee'; g.fill();
  const top = 36 + (h - 160) * (1 - level);
  roundRect(g, cx - 18, top, 36, h - 100 - top, 18); g.fillStyle = color; g.fill();
  g.beginPath(); g.arc(cx, h - 70, 40, 0, Math.PI * 2); g.fill();
  g.fillStyle = 'rgba(255,255,255,0.55)'; roundRect(g, cx - 10, top + 8, 8, Math.max(0, h - 130 - top), 4); g.fill();
}
export function phoneScreenTexture() {
  return canvasTex(256, 512, (g, w, h) => {
    const grd = g.createLinearGradient(0, 0, 0, h); grd.addColorStop(0, '#4fa3ff'); grd.addColorStop(1, '#7b5cff');
    g.fillStyle = grd; g.fillRect(0, 0, w, h);
    g.fillStyle = 'rgba(255,255,255,0.85)';
    for (let i = 0; i < 3; i++) for (let j = 0; j < 4; j++) { roundRect(g, 30 + i * 70, 120 + j * 80, 50, 50, 14); g.fill(); }
    g.fillStyle = 'rgba(255,255,255,0.9)'; roundRect(g, 60, 30, 136, 30, 15); g.fill();
  });
}
export function panelTexture() {
  // light interior wall panels with seams + rivets (albedo)
  return canvasTex(512, 512, (g, w, h) => {
    g.fillStyle = '#e9e4dc'; g.fillRect(0, 0, w, h);
    g.strokeStyle = 'rgba(80,70,60,0.35)'; g.lineWidth = 4;
    for (let i = 0; i <= 2; i++) { g.beginPath(); g.moveTo(i * w / 2, 0); g.lineTo(i * w / 2, h); g.stroke(); }
    g.beginPath(); g.moveTo(0, h / 2); g.lineTo(w, h / 2); g.stroke();
    g.fillStyle = 'rgba(90,80,70,0.35)';
    for (let i = 0; i < 2; i++) for (let j = 0; j < 2; j++) for (const [a, b] of [[14, 14], [w / 2 - 14, 14], [14, h / 2 - 14], [w / 2 - 14, h / 2 - 14]]) {
      g.beginPath(); g.arc(i * w / 2 + a, j * h / 2 + b, 4, 0, Math.PI * 2); g.fill();
    }
  });
}
export function rugTexture() {
  return canvasTex(512, 512, (g, w, h) => {
    g.fillStyle = '#c96a4a'; g.fillRect(0, 0, w, h);
    g.strokeStyle = '#f0c27b'; g.lineWidth = 18;
    for (let k = 0; k < 4; k++) { g.beginPath(); g.ellipse(w / 2, h / 2, w * (0.44 - k * 0.1), h * (0.44 - k * 0.1), 0, 0, Math.PI * 2); g.stroke(); }
  });
}
export function treadTexture() {
  return canvasTex(256, 64, (g, w, h) => {
    g.fillStyle = '#3a3d42'; g.fillRect(0, 0, w, h);
    g.fillStyle = '#25272b';
    for (let i = 0; i < 16; i++) g.fillRect(i * 16, 0, 8, h);
  });
}
